  } else {
    // Interpret offset as offset in output components.
    for (size_t i = 0; i < out->size; ++i) {
      for (size_t c = 0; c < NCOM(inp); ++c) {
        out_d[i * NCOM(out) + c + coff] += a * inp_d[i * NCOM(inp) + c];
