    if not offsets:
        return text
    chars = list(text)
    for off in reversed(offsets):
        del chars[off]
    return "".join(chars)


def add_trailing_commas(text):
    m = _mask(text)
    inserts = []
    stack = []
    for i, ch in enumerate(m):
        if ch == "{":
