    long linidx_phase = gkyl_range_idx(mask_rng, pidx);
    const double *arr_c = gkyl_array_cfetch(arr_in, linidx_phase);
    double abs_val = fabs(arr_c[0]);

    if (abs_val > local_max) {
      local_max = abs_val;
    }
  }

  return local_max;
}

